import { test, expect } from '@playwright/test';

test.describe('Polling Stopping on Navigation Away', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/polling-page');
  });

  test('should stop polling when user navigates away from the polling page', async ({ page }) => {
    // Verify polling is active
    const pollingInterval = page.getByRole('heading', { name: /polling interval/i });
    await expect(pollingInterval).toBeVisible();

    const pollingStatus = page.getByText(/polling in progress/i);
    await expect(pollingStatus).toBeVisible();

    // Verify polling data is displayed
    const pollingData = page.getByText(/data received/i);
    await expect(pollingData).toBeVisible();

    // Verify polling interval is set
    const intervalElement = page.getByRole('heading', { name: /polling interval/i });
    await expect(intervalElement).toBeVisible();

    // Verify polling is active
    const pollingStatus = page.getByText(/polling in progress/i);
    await expect(pollingStatus).toBeVisible();

    // Navigate away from the page
    const navButton = page.getByRole('button', { name: /go back/i });
    await navButton.click();

    // Wait for navigation to complete
    await page.waitForLoadState('networkidle');

    // Verify polling has stopped
    const pollingStatus = page.getByText(/polling in progress/i);
    await expect(pollingStatus).not.toBeVisible();

    // Verify polling interval is no longer set
    const intervalElement = page.getByRole('heading', { name: /polling interval/i });
    await expect(intervalElement).not.toBeVisible();

    // Verify polling data is no longer displayed
    const pollingData = page.getByText(/data received/i);
    await expect(pollingData).not.toBeVisible();

    // Verify user is now on the home page
    const homePageTitle = page.getByRole('heading', { name: /home/i });
    await expect(homePageTitle).toBeVisible();
  });

  test('should handle navigation away from polling page with error state', async ({ page }) => {
    // Set up polling with error state
    await page.route('**/api/polling', (route) => {
      route.abort('Polling error');
    });

    // Verify polling is active
    const pollingInterval = page.getByRole('heading', { name: /polling interval/i });
    await expect(pollingInterval).toBeVisible();

    const pollingStatus = page.getByText(/polling in progress/i);
    await expect(pollingStatus).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/polling failed/i);
    await expect(errorMessage).toBeVisible();

    // Navigate away from the page
    const navButton = page.getByRole('button', { name: /go back/i });
    await navButton.click();

    // Wait for navigation to complete
    await page.waitForLoadState('networkidle');

    // Verify polling has stopped
    const pollingStatus = page.getByText(/polling in progress/i);
    await expect(pollingStatus).not.toBeVisible();

    // Verify error message is still visible
    const errorMessage = page.getByText(/polling failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is now on the home page
    const homePageTitle = page.getByRole('heading', { name: /home/i });
    await expect(homePageTitle).toBeVisible();
  });
});
